-- germany.ahr.walporzheim-ahrtal
insert into public.wine_place_articles (wine_place_id, description, climate, soils, key_facts, editorial_status)
select id, 'The Ahr''s single Bereich, which covers effectively the whole region: a narrow slate gorge west of the Rhine where Germany makes some of its most serious Pinot Noir. Vineyards are terraced into dark slate and greywacke on slopes reaching sixty degrees, and it is the valley''s heat-trapping walls that let red grapes ripen this far north at all.', 'Sheltered and surprisingly warm for 50°N. The narrow valley holds heat and the dark slate radiates it back at night, which is why red varieties dominate here while the rest of Germany plants white.', 'Devonian slate and greywacke, thin and stony, on terraces cut into very steep slopes.', array['Germany''s red-wine valley — Spätburgunder above all', 'Slate terraces on slopes up to sixty degrees', 'Covers effectively the whole Ahr region', 'Rebuilt after the July 2021 flood']::text[], 'PUBLISHED'
  from public.wine_places where canonical_key = 'germany.ahr.walporzheim-ahrtal';
insert into public.wine_place_styles (wine_place_id, style, sort_order, editorial_status)
