-- germany.hessische-bergstrasse.umstadt
insert into public.wine_place_articles (wine_place_id, description, climate, soils, key_facts, editorial_status)
select id, 'A detached pocket of vineyard around Groß-Umstadt, some thirty kilometres north-east of the main Bergstraße and separated from it by the Odenwald. Long known as the Odenwälder Weininsel — the Odenwald''s wine island — it is small, warm, and almost entirely drunk within sight of where it grew.', 'More continental than the Bergstraße proper, sitting in a basin east of the Odenwald rather than on the Rhine plain.', 'Weathered granite and diorite of the Odenwald basement, capped in places by loess and loam.', array['A detached exclave, not joined to the Bergstraße', 'Known as the Odenwälder Weininsel', 'Centred on Groß-Umstadt']::text[], 'PUBLISHED'
