-- germany.mittelrhein.loreley
insert into public.wine_place_articles (wine_place_id, description, climate, soils, key_facts, editorial_status)
select id, 'The Mittelrhein''s southern and far larger Bereich, following the Rhine gorge through the UNESCO-listed stretch past the Loreley rock. Riesling grows on terraces so steep and so narrow that much of the vineyard has been abandoned over the last century, leaving a small number of growers working some of the most dramatic sites in Germany.', 'Cool and windy in the gorge, with the river moderating the extremes. Ripening depends on slope and aspect more than on anything else.', 'Devonian slate and quartzite, thin over rock, on terraces held by dry-stone walls.', array['Follows the UNESCO-listed Rhine Gorge', 'Riesling on very steep slate terraces', 'Much of the historic vineyard has been abandoned']::text[], 'PUBLISHED'
