-- germany.mosel.bernkastel
insert into public.wine_place_articles (wine_place_id, description, climate, soils, key_facts, editorial_status)
select id, 'The Middle Mosel, and the heart of the region''s reputation: the loop of river from Trittenheim down through Piesport, Brauneberg, Bernkastel, Wehlen and Zeltingen. Blue Devonian slate, south-facing slopes of extraordinary steepness, and a roll-call of vineyard names — Doctor, Sonnenuhr, Juffer — that set the standard for Riesling everywhere.', 'Cool continental, rescued by the river''s reflected light and by slopes angled to catch every available hour of sun.', 'Blue Devonian slate, weathering to a stony topsoil that holds the day''s heat into the night.', array['The Middle Mosel — the region''s greatest sites', 'Bernkasteler Doctor, Wehlener Sonnenuhr, Brauneberger Juffer', 'Blue Devonian slate', 'Riesling almost to the exclusion of everything else']::text[], 'PUBLISHED'
