-- germany.mosel.burg-cochem
insert into public.wine_place_articles (wine_place_id, description, climate, soils, key_facts, editorial_status)
select id, 'The Lower Mosel, from Zell down to Koblenz, and better known to growers as the Terrassenmosel. Here the valley narrows and the slate is worked in small walled terraces rather than open slope — including the Bremmer Calmont, among the steepest vineyards anywhere. Yields are tiny and the work is entirely by hand.', 'Cool, with the narrow valley and dark slate holding what warmth there is. Frost and erosion are constant concerns.', 'Devonian slate in thin terraced pockets, held by dry-stone walls that are themselves a large part of the cost of farming here.', array['The Terrassenmosel — dry-stone terraces, not open slope', 'Bremmer Calmont, among the world''s steepest vineyards', 'Worked entirely by hand']::text[], 'PUBLISHED'
  from public.wine_places where canonical_key = 'germany.mosel.burg-cochem';
insert into public.wine_place_styles (wine_place_id, style, sort_order, editorial_status)
