-- germany.mosel.obermosel
insert into public.wine_place_articles (wine_place_id, description, climate, soils, key_facts, editorial_status)
select id, 'The Upper Mosel, upstream of Trier along the Luxembourg border, and the one part of the region that is not slate at all. Vines grow on Muschelkalk shell-limestone, and the traditional grape is Elbling — ancient, neutral and sharply acidic — much of which becomes Sekt rather than still wine.', 'Cool and continental, marginally warmer than the slate Mosel downstream but without the heat-storing rock that makes those slopes work.', 'Muschelkalk shell-limestone, not slate. That single difference sets the whole Bereich apart from the rest of the Mosel.', array['Limestone, not slate', 'Elbling, an ancient and sharply acidic white', 'Much of the crop becomes Sekt', 'Faces Luxembourg across the river']::text[], 'PUBLISHED'
  from public.wine_places where canonical_key = 'germany.mosel.obermosel';
insert into public.wine_place_styles (wine_place_id, style, sort_order, editorial_status)
select id, 'WHITE', 0, 'PUBLISHED' from public.wine_places where canonical_key = 'germany.mosel.obermosel';
insert into public.wine_place_styles (wine_place_id, style, sort_order, editorial_status)
