-- germany.mosel.ruwer
insert into public.wine_place_articles (wine_place_id, description, climate, soils, key_facts, editorial_status)
select id, 'A small tributary valley east of Trier, cooler than the Mosel itself, making Riesling of unusual delicacy — low in alcohol, high in acid, and among the longest-lived wine in Germany. Two estates, Maximin Grünhaus and Karthäuserhof, carry most of its reputation.', 'Cool even by Mosel standards. The Ruwer is a small stream with none of the Mosel''s heat-storing mass, so ripening is late and genuinely marginal.', 'Devonian slate, with some red sandstone and gravel in the valley floor.', array['Cooler than the Mosel proper', 'Riesling of great delicacy and longevity', 'Maximin Grünhaus and Karthäuserhof']::text[], 'PUBLISHED'
  from public.wine_places where canonical_key = 'germany.mosel.ruwer';
