 where p.canonical_key = 'germany.mosel.ruwer' and g.name = 'Riesling';

-- germany.mosel.saar
insert into public.wine_place_articles (wine_place_id, description, climate, soils, key_facts, editorial_status)
select id, 'The Saar joins the Mosel south of Trier, and in a good year makes the most piercing Riesling in Germany — steely, taut and unmistakably cool-climate, with Scharzhofberg as its most famous site. In poor years the grapes barely ripen at all, which is why the Saar''s reputation rests on its best vintages rather than its average one.', 'The coldest corner of the Mosel: exposed, late-ripening, and marginal in the literal sense.', 'Grey Devonian slate, often mixed with quartzite.', array['The coolest and steeliest corner of the Mosel', 'Scharzhofberg', 'Marginal ripening — vintage matters more here than anywhere']::text[], 'PUBLISHED'
  from public.wine_places where canonical_key = 'germany.mosel.saar';
insert into public.wine_place_styles (wine_place_id, style, sort_order, editorial_status)
