 where p.canonical_key = 'germany.mosel.saar' and g.name = 'Riesling';

-- germany.nahe.nahetal
insert into public.wine_place_articles (wine_place_id, description, climate, soils, key_facts, editorial_status)
select id, 'The Nahe''s single Bereich, covering the whole region along the river between Bingen and Bad Kreuznach and up its side valleys. Its defining feature is geological variety — volcanic porphyry, slate, quartzite, sandstone and loam within a few kilometres — which is why Nahe Riesling is so often described as sitting between the Mosel''s delicacy and the Rheingau''s weight.', 'Sheltered by the Hunsrück to the north-west, and among the drier and sunnier parts of German wine country.', 'Unusually varied over a short distance: volcanic porphyry and melaphyre around Schlossböckelheim, slate and quartzite upstream, sandstone and loam downstream.', array['One Bereich covering the whole Nahe', 'Exceptionally varied geology over a few kilometres', 'Riesling between Mosel delicacy and Rheingau weight']::text[], 'PUBLISHED'
  from public.wine_places where canonical_key = 'germany.nahe.nahetal';
