-- germany.pfalz.mittelhaardt-dt-weinstrasse
insert into public.wine_place_articles (wine_place_id, description, climate, soils, key_facts, editorial_status)
select id, 'The northern half of the Pfalz and the source of most of its finest wine: a warm strip below the Haardt hills running through Kallstadt, Ungstein, Bad Dürkheim, Wachenheim, Forst, Deidesheim and Ruppertsberg. Forster Kirchenstück and Jesuitengarten and their neighbours give Riesling more weight and ripeness than anywhere further north.', 'One of Germany''s warmest and driest stretches, sheltered by the Haardt. Figs and almonds grow along the Weinstraße.', 'Loam and sandstone with limestone, and at Forst the black basalt that was carted onto the vineyards to hold heat.', array['The Pfalz''s finest strip — Forst, Deidesheim, Wachenheim', 'Riesling with unusual weight and ripeness', 'Basalt at Forst, carted in to hold heat']::text[], 'PUBLISHED'
