-- germany.pfalz.suedl-weinstrasse
insert into public.wine_place_articles (wine_place_id, description, climate, soils, key_facts, editorial_status)
select id, 'The southern Pfalz, from Neustadt down to the French border, where the Alsace climate begins to make itself felt. Long a source of bulk wine, it has been transformed over the last thirty years into Germany''s most convincing home for Pinot — Weiss-, Grau- and Spätburgunder — alongside increasingly serious Riesling.', 'The warmest stretch of German vineyard, continuous with Alsace across the border.', 'Loess, loam, limestone and coloured sandstone.', array['Germany''s warmest vineyards, continuous with Alsace', 'Transformed from bulk wine to serious Pinot', 'Weiss-, Grau- and Spätburgunder together']::text[], 'PUBLISHED'
  from public.wine_places where canonical_key = 'germany.pfalz.suedl-weinstrasse';
