-- germany.rheingau.johannisberg
insert into public.wine_place_articles (wine_place_id, description, climate, soils, key_facts, editorial_status)
select id, 'The Rheingau''s single Bereich, named after the hill at Schloss Johannisberg and covering the entire region — the south-facing bank from Hochheim west to Lorch, plus Assmannshausen around the bend where the river turns north again. One Bereich for one of the most tightly drawn wine regions in Germany.', 'Warm for its latitude, sheltered by the Taunus to the north, with the broad river storing heat and lengthening the autumn.', 'Quartzite and slate at the steep western end around Rüdesheim; loess, marl and sandy loam through the gentler middle.', array['One Bereich covering the whole Rheingau', 'Named for the hill at Schloss Johannisberg', 'Riesling on about three-quarters of the vineyard']::text[], 'PUBLISHED'
  from public.wine_places where canonical_key = 'germany.rheingau.johannisberg';
insert into public.wine_place_styles (wine_place_id, style, sort_order, editorial_status)
