-- germany.rheinhessen.bingen
insert into public.wine_place_articles (wine_place_id, description, climate, soils, key_facts, editorial_status)
select id, 'Rheinhessen''s north-western corner, facing the Nahe across the water at Bingen and the Rheingau across the Rhine to the north. Quartzite and slate on the Scharlachberg give a firmer, more mineral Riesling than most of the gentler country to the south.', 'Mild and dry, with the Nahe and the Rhine meeting here to moderate it.', 'Quartzite and slate on the Scharlachberg; loess and loam elsewhere.', array['Rheinhessen''s north-west corner, at the Nahe''s mouth', 'Quartzite and slate on the Scharlachberg', 'Faces the Rheingau across the river']::text[], 'PUBLISHED'
  from public.wine_places where canonical_key = 'germany.rheinhessen.bingen';
