-- germany.rheinhessen.nierstein
insert into public.wine_place_articles (wine_place_id, description, climate, soils, key_facts, editorial_status)
select id, 'The Rheinterrasse — the short east-facing bank between Nackenheim and Oppenheim, and the best vineyard land in Rheinhessen. The Roter Hang, a band of iron-red Rotliegend slate found nowhere else in Germany, runs through Nackenheimer Rothenberg and Niersteiner Pettenthal and Hipping, and gives Riesling an unmistakable smoky depth.', 'Warm and sheltered, with the wide river reflecting light onto slopes that face due east and take the morning sun.', 'The Roter Hang''s red Rotliegend slate and sandstone, unique in German wine, giving way to loess further inland.', array['The Rheinterrasse — Rheinhessen''s finest bank', 'The Roter Hang''s iron-red Rotliegend slate', 'Pettenthal, Hipping, Rothenberg']::text[], 'PUBLISHED'
  from public.wine_places where canonical_key = 'germany.rheinhessen.nierstein';
