-- germany.rheinhessen.wonnegau
insert into public.wine_place_articles (wine_place_id, description, climate, soils, key_facts, editorial_status)
select id, 'Southern Rheinhessen, between Alzey and Worms, whose name means roughly the delightful district. Anonymous for most of the last century, it is now the address of several of Germany''s most talked-about growers, working Riesling on limestone and clay around Westhofen and Flörsheim-Dalsheim. Worms itself gave the world Liebfraumilch, named for the Liebfrauenstift vineyard beside the church.', 'Warm and dry, and a little more continental than the river terrace to the north-east.', 'Limestone, clay and marl, with loess over much of the gentler land.', array['Westhofen and Flörsheim-Dalsheim', 'Limestone and clay rather than river slate', 'Liebfraumilch takes its name from Worms'' Liebfrauenstift']::text[], 'PUBLISHED'
  from public.wine_places where canonical_key = 'germany.rheinhessen.wonnegau';
