    ('italy.basilicata.vulture', 1, 1, 1),
    ('italy.calabria.ionio-crotonese', 2, 2, 1),
    ('italy.calabria.locride', 2, 1, 1),
    ('italy.campania.irpinia', 2, 3, 1),
    ('italy.campania.sannio', 2, 2, 1),
    ('italy.emilia-romagna.emilia', 2, 2, 1),
    ('italy.emilia-romagna.romagna', 2, 3, 1),
