    ('italy.valle-d-aosta.valdigne', 1, 1, 1),
    ('italy.trentino-alto-adige.alto-adige', 2, 8, 1),
    ('italy.trentino-alto-adige.trentino', 3, 1, 1),
    ('italy.veneto.bardolino', 2, 3, 1),
    ('italy.veneto.conegliano-valdobbiadene-prosecco', 1, 1, 1),
    ('italy.veneto.soave', 1, 2, 1),
    ('italy.veneto.valpolicella', 2, 4, 1)
    ) as t(key, want_styles, want_grapes, want_article)
  loop
    select count(*) into n from public.wine_place_styles s
      join public.wine_places p on p.id = s.wine_place_id where p.canonical_key = r.key;
    if n <> r.want_styles then
      raise exception '%: % style rows, expected %', r.key, n, r.want_styles;
    end if;
    select count(*) into n from public.wine_place_grapes g
      join public.wine_places p on p.id = g.wine_place_id where p.canonical_key = r.key;
    if n <> r.want_grapes then
      raise exception '%: % grape rows, expected % — a grape name did not resolve', r.key, n, r.want_grapes;
    end if;
    select count(*) into n from public.wine_place_articles a
      join public.wine_places p on p.id = a.wine_place_id where p.canonical_key = r.key;
    if n < r.want_article then
      raise exception '%: no article', r.key;
    end if;
  end loop;

  -- No German or Italian region or subregion is left without styles.
  select count(*) into n from public.wine_places p
   where p.kind in ('REGION','SUBREGION')
     and (p.canonical_key like 'germany.%' or p.canonical_key like 'italy.%')
     and not exists (select 1 from public.wine_place_styles s where s.wine_place_id = p.id);
  if n <> 0 then raise exception '% German/Italian places still have no wine styles', n; end if;

  select count(*) into n from public.wine_places p
   where p.kind in ('REGION','SUBREGION') and p.canonical_key like 'germany.%'
     and not exists (select 1 from public.wine_place_articles a where a.wine_place_id = p.id);
  if n <> 0 then raise exception '% German places still have no article', n; end if;
end $$;

